create extension if not exists pgcrypto;
create table if not exists public.products (id uuid primary key default gen_random_uuid(), name text not null, description text default '', price text default '', image_url text default '', emoji text default '', available boolean not null default true);
create table if not exists public.product_images (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, image_url text not null, caption text default '', created_at timestamptz not null default now());
create table if not exists public.site_sections (key text primary key, title text not null, body text not null, updated_at timestamptz not null default now());
alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.site_sections enable row level security;
drop policy if exists products_read on public.products; create policy products_read on public.products for select using (true); drop policy if exists products_write on public.products; create policy products_write on public.products for all to authenticated using (true) with check (true);
drop policy if exists images_read on public.product_images; create policy images_read on public.product_images for select using (true); drop policy if exists images_write on public.product_images; create policy images_write on public.product_images for all to authenticated using (true) with check (true);
drop policy if exists sections_read on public.site_sections; create policy sections_read on public.site_sections for select using (true); drop policy if exists sections_write on public.site_sections; create policy sections_write on public.site_sections for all to authenticated using (true) with check (true);
insert into public.site_sections(key,title,body) values ('about','درباره آرا','آرا همراه شما برای مراقبت بهتر از پرندگان خانگی است.'),('care','مراقبت','محیط آرام، آب تازه و غذای متنوع برای سلامت پرنده ضروری است.'),('contact','تماس','تماس با آرا: ۰۹۱۰۷۴۸۸۰۱۳') on conflict (key) do nothing;
insert into storage.buckets(id,name,public) values ('product-images','product-images',true) on conflict (id) do update set public=true;
drop policy if exists storage_public_read on storage.objects; create policy storage_public_read on storage.objects for select using (bucket_id='product-images'); drop policy if exists storage_auth_write on storage.objects; create policy storage_auth_write on storage.objects for all to authenticated using (bucket_id='product-images') with check (bucket_id='product-images');